// On-demand expand: fetch ONE public VTADetails page and POST its HTML to the
// app's /api/rover/ingest (the app extracts + gates). Single, polite fetch — no
// paging, no grid, no cookies (VTADetails is public).
//
// Config (appBaseUrl + ingestToken) arrives in the webhook PAYLOAD from the app —
// this n8n blocks $env access in Code nodes, and payload-passing keeps the workflow
// secret-free (the app reads them from process.env).
const HOST = 'https://www.rover.infrastructure.gov.au';
const UA = 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36';
const helpers = this.helpers;
const payload = $json && $json.body ? $json.body : ($json || {});
const APP = (payload.appBaseUrl || 'https://tbr.dev.ragebots.me').replace(/\/$/, '');
const TOKEN = payload.ingestToken || '';
const approvalId = payload.approvalId;
const vta = payload.vtaNumber || null;
if (!approvalId) throw new Error('expand webhook called without approvalId');
if (!TOKEN) throw new Error('expand webhook called without ingestToken');
// 1. fetch the public VTADetails page
const det = await helpers.httpRequest({ method: 'GET', url: HOST + '/PublishedApprovals/VTADetails/?id=' + encodeURIComponent(approvalId), headers: { 'User-Agent': UA, Accept: 'text/html', 'Accept-Language': 'en-AU,en;q=0.9' }, returnFullResponse: true, ignoreHttpStatusErrors: true });
if ([403, 429, 503].includes(det.statusCode)) throw new Error('ROVER detail ' + det.statusCode + ' for ' + approvalId + ' — possible block; aborting');
if (det.statusCode >= 400) return [{ json: { ok: false, vtaNumber: vta, approvalId, error: 'detail ' + det.statusCode } }];
// 2. POST the HTML to the app — it extracts the inline PDFs, parses, archives, gates
const ing = await helpers.httpRequest({ method: 'POST', url: APP + '/api/rover/ingest/', headers: { Authorization: 'Bearer ' + TOKEN, 'Content-Type': 'application/json' }, body: JSON.stringify({ detailHtml: String(det.body) }), returnFullResponse: true, ignoreHttpStatusErrors: true });
const parsed = typeof ing.body === 'string' ? (() => { try { return JSON.parse(ing.body); } catch (e) { return {}; } })() : (ing.body || {});
if (ing.statusCode >= 400) return [{ json: { ok: false, vtaNumber: vta, approvalId, error: 'ingest ' + ing.statusCode, detail: String(ing.body).slice(0, 200) } }];
return [{ json: { ok: true, vtaNumber: parsed.vtaNumber || vta, approvalId, variantsCreated: parsed.variantsCreated, variantsRefreshed: parsed.variantsRefreshed, amendment: parsed.amendment && parsed.amendment.status } }];
